/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  localparam WIDTH=8;
  localparam DEPTH=4;
  reg clk=0, rst_n=0, winc=0, rinc=0;
  reg [WIDTH-1:0] wdata=0;
  wire wfull, rempty;
  wire [WIDTH-1:0] rdata;

  TopModule #(.WIDTH(WIDTH), .DEPTH(DEPTH)) dut (
    .clk(clk), .rst_n(rst_n), .winc(winc), .rinc(rinc), .wdata(wdata),
    .wfull(wfull), .rempty(rempty), .rdata(rdata)
  );

  always #5 clk = ~clk;

  task tick;
    begin
      #1;
      @(posedge clk);
      #1;
      "'$display("t=%0t winc=%0b rinc=%0b wdata=%0h wfull=%0b rempty=%0b waddr=%0d:%0d raddr=%0d:%0d rdata=%0h",
        $time, winc, rinc, wdata, wfull, rempty,
        dut.waddr[$clog2(DEPTH)], dut.waddr[$clog2(DEPTH)-1:0],
        dut.raddr[$clog2(DEPTH)], dut.raddr[$clog2(DEPTH)-1:0], rdata);
    end
  endtask

  integer i;
  initial begin
    tick();
    rst_n=1;
    // fill fifo
    for (i=0;i<DEPTH;i=i+1) begin
      winc=1; wdata=i+8'"'hA0; rinc=0; tick();
    end
    winc=0; tick();
    // drain fifo
    for (i=0;i<DEPTH;i=i+1) begin
      rinc=1; winc=0; tick();
    end
    rinc=0; tick();
    "'$finish;
  end
endmodule
EOF
